CREATE PROCEDURE "DA_KMEANS_CLEAN" (IN SCHEMANAME VARCHAR(100), IN SUFFIX VARCHAR(50)) LANGUAGE SQLSCRIPT  SQL SECURITY INVOKER  AS BEGIN     DECLARE ROWCNT INTEGER;     DECLARE PROCEDURENAME VARCHAR(150);     PROCEDURENAME = 'DA_KMEANS_PROC_' || :SUFFIX;     EXECUTE IMMEDIATE 'CALL "SYS".AFLLANG_WRAPPER_PROCEDURE_DROP(''' || :SCHEMANAME || ''', ''' || :PROCEDURENAME || ''')';     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_DATA_T_' || :SUFFIX);     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_CONTROL_T_' || :SUFFIX);     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_ASSIGNED_T_' || :SUFFIX);     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_CENTERS_T_' || :SUFFIX);         CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_SIL_CENTERS_T_' || :SUFFIX);     CALL DA_DROP_TYPE(:SCHEMANAME, 'DA_KMEANS_STATISTIC_T_' || :SUFFIX);     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_PDATA_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_KMEANS_PDATA_TBL;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_ASSIGNED_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_KMEANS_ASSIGNED_TBL;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_CENTERS_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_KMEANS_CENTERS_TBL;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_SIL_CENTERS_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_KMEANS_SIL_CENTERS_TBL;     END IF;     SELECT COUNT(*) INTO ROWCNT FROM "PUBLIC"."M_TEMPORARY_TABLES" WHERE TABLE_NAME='#DA_KMEANS_STATISTIC_TBL' AND CONNECTION_ID=CURRENT_CONNECTION;     IF ROWCNT>0 THEN         DROP TABLE #DA_KMEANS_STATISTIC_TBL;     END IF; END
